const row = (title: string, subtitle: string, meta?: string, status?: string, target?: string) => ({ title, subtitle, meta, status, target })

function screen(
  id: string,
  group: string,
  title: string,
  description: string,
  roles: PrototypeRole[],
  kind: ScreenKind,
  extra: Partial<ScreenDefinition> = {},
): ScreenDefinition {
  return { id, group, title, description, roles, kind, ...extra }
}

