export const screenManifest: ScreenDefinition[] = [
  ...authScreens,
  ...coreScreens,
  ...scheduleScreens,
  ...clientManagementScreens,
  ...portalScreens,
  ...teacherScreens,
  ...analyticsScreens,
  ...settingsScreens,
  ...chatAndProfileScreens,
  ...systemScreens,
]

export const screenById = new Map(screenManifest.map((item) => [item.id, item]))
export const screenGroups = [...new Set(screenManifest.map((item) => item.group))]

export function validateScreenManifest() {
  const ids = new Set<string>()
  const duplicateIds: string[] = []
  const brokenTargets: Array<{ from: string; target: string }> = []

  for (const item of screenManifest) {
    if (ids.has(item.id)) duplicateIds.push(item.id)
    ids.add(item.id)
  }
  for (const item of screenManifest) {
    const targets = [
      ...(item.actions ?? []).map((action) => action.target),
      ...(item.tabs ?? []).map((tab) => tab.target),
      ...(item.rows ?? []).flatMap((entry) => entry.target ? [entry.target] : []),
    ]
    for (const target of targets) {
      if (!ids.has(target)) brokenTargets.push({ from: item.id, target })
    }
  }

  return { total: screenManifest.length, unique: ids.size, duplicateIds, brokenTargets, valid: duplicateIds.length === 0 && brokenTargets.length === 0 }
}

export function withState(entry: ScreenDefinition, state: ScreenState): ScreenDefinition {
  if (state === 'content') return entry
  return { ...entry, state, id: entry.id, actions: [{ label: state === 'loading' ? 'Показать данные' : 'Повторить', target: entry.id }] }
}
